/**
 * Tests for dsh-chem. All numeric anchors are generated by the independent
 * Python oracle test/anchors-chem.py (own periodic table + own tokenizer +
 * own Fraction-based equation balancer) and cross-validated against published
 * textbook values (molar masses, balanced coefficients, 22.414 L/mol at STP).
 *
 * ORACLE: test/anchors-chem.py
 *
 * Discipline: every result object is checked with assertLossless (lossless
 * JSON gate), and argument helpers only assign keys that are present.
 *
 * @module dsh-chem/test
 */

import { describe, expect, it } from 'vitest'
import { buildChemTools } from '../src/tools.ts'
import { parseFormula, formulaMass, AVOGADRO } from '../src/core.ts'
import { assertLossless } from './helpers/lossless-json.ts'

/* ------------------------------------------------------------------ */
/* helpers                                                             */
/* ------------------------------------------------------------------ */

const tools = buildChemTools()

const executeFormulaMass = tools.formula_mass.execute as (args: { formula: string }) => Promise<Record<string, unknown>>
const executeBalance = tools.balance_equation.execute as (args: { equation: string }) => Promise<Record<string, unknown>>
const executeGasLaw = tools.gas_law.execute as (args: Record<string, unknown>) => Promise<Record<string, unknown>>
const executeMassMoles = tools.mass_moles.execute as (args: {
  mode: string
  value: number
  formula?: string
  molarMass?: number
}) => Promise<Record<string, unknown>>
const executeSolution = tools.solution.execute as (args: Record<string, unknown>) => Promise<Record<string, unknown>>
const executePh = tools.ph.execute as (args: Record<string, unknown>) => Promise<Record<string, unknown>>

/** Build args with only defined keys (args-side lossless JSON discipline). */
function pick(entries: Record<string, unknown>): Record<string, unknown> {
  const result: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(entries)) {
    if (value !== undefined) result[key] = value
  }
  return result
}

/** Relative error between two finite numbers. */
function relErr(actual: number, expected: number): number {
  return Math.abs(actual - expected) / Math.abs(expected)
}

