const ERROR_FORMULAS = [
  '',
  '   ',
  'Xx',
  'H0',
  '(NH4',
  'NH4)2',
  'CuSO4··5H2O',
  'Fe3+Cl',
  'Na2SO4+2',
  '2',
  'H2O..',
  'nacl',
  'co2x',
]

describe('formula parser (core)', () => {
  for (const anchor of MASS_ANCHORS) {
    it(`parses ${anchor.formula} -> ${anchor.mass}`, () => {
      const parsed = parseFormula(anchor.formula)
      expect(parsed.ok).toBe(true)
      if (!parsed.ok) return
      const mass = formulaMass(parsed)
      expect(relErr(mass.molarMass, anchor.mass)).toBeLessThan(1e-9)
      const counts: Record<string, number> = {}
      for (const t of parsed.totals) counts[t.symbol] = t.count
      for (const [symbol, count] of Object.entries(anchor.counts!)) {
        expect(counts[symbol], `count of ${symbol} in ${anchor.formula}`).toBe(count)
      }
      expect(Object.keys(counts).sort()).toEqual(Object.keys(anchor.counts!).sort())
      // mass fractions sum to 1 (within FP dust)
      const sum = mass.breakdown.reduce((acc, b) => acc + b.massFraction, 0)
      expect(Math.abs(sum - 1)).toBeLessThan(1e-9)
    })
  }

  it('parses hydrate water counts', () => {
    const parsed = parseFormula('CuSO4·5H2O')
    expect(parsed.ok).toBe(true)
    if (!parsed.ok) return
    expect(parsed.hydrate).toEqual([
      { symbol: 'H', count: 10 },
      { symbol: 'O', count: 5 },
    ])
    expect(parsed.normalized).toBe('CuSO4·5H2O')
  })

  it('parses asterisk hydrate separator', () => {
    const parsed = parseFormula('CuSO4*5H2O')
    expect(parsed.ok).toBe(true)
    if (!parsed.ok) return
    expect(formulaMass(parsed).molarMass).toBeCloseTo(249.677, 6)
  })

  it('parses leading coefficient', () => {
    const parsed = parseFormula('2H2O')
    expect(parsed.ok).toBe(true)
    if (!parsed.ok) return
    expect(parsed.coefficient).toBe(2)
    expect(formulaMass(parsed).molarMass).toBeCloseTo(18.015, 6)
    expect(parsed.normalized).toBe('2H2O')
  })

  for (const anchor of CHARGE_ANCHORS) {
    it(`charge rule: ${anchor.formula} -> mass ${anchor.mass}, charge ${anchor.charge}`, () => {
      const parsed = parseFormula(anchor.formula)
      expect(parsed.ok).toBe(true)
      if (!parsed.ok) return
      expect(parsed.charge).toBe(anchor.charge)
      expect(relErr(formulaMass(parsed).molarMass, anchor.mass)).toBeLessThan(1e-9)
      const counts: Record<string, number> = {}
      for (const t of parsed.totals) counts[t.symbol] = t.count
      expect(counts).toEqual(anchor.counts)
    })
  }

  for (const bad of ERROR_FORMULAS) {
    it(`rejects invalid formula ${JSON.stringify(bad)}`, () => {
      const parsed = parseFormula(bad)
      expect(parsed.ok).toBe(false)
    })
  }

  it('reports radioelement mass-number usage', () => {
    const parsed = parseFormula('Tc')
    expect(parsed.ok).toBe(true)
    if (!parsed.ok) return
    const mass = formulaMass(parsed)
    expect(mass.usedMassNumber).toBe(true)
    expect(mass.breakdown[0]!.name).toBe('Technetium')
  })

  it('orders breakdown by atomic number', () => {
    const parsed = parseFormula('NaCl')
    expect(parsed.ok).toBe(true)
    if (!parsed.ok) return
    const symbols = formulaMass(parsed).breakdown.map((b) => b.symbol)
    expect(symbols).toEqual(['Na', 'Cl'])
  })
})

/* ------------------------------------------------------------------ */
/* formula_mass tool (defineTool wrapper + output discipline)          */
/* ------------------------------------------------------------------ */

describe('formula_mass tool', () => {
  it('computes H2SO4 molar mass with breakdown', async () => {
    const result = await executeFormulaMass({ formula: 'H2SO4' })
    assertLossless(result)
    expect(result.valid).toBe(true)
    expect(relErr(result.molarMass as number, 98.072)).toBeLessThan(1e-9)
    expect((result.elements as Array<{ symbol: string }>).map((e) => e.symbol).join('')).toBe('HOS')
    const sulfur = (result.elements as Array<Record<string, number>>).find((e) => e.symbol === 'S')!
    expect(sulfur.massFraction).toBeCloseTo(32.06 / 98.072, 9)
  })

  it('returns valid:false with error for a bad formula', async () => {
    const result = await executeFormulaMass({ formula: 'Fe3+Cl' })
    assertLossless(result)
    expect(result.valid).toBe(false)
    expect(typeof result.error).toBe('string')
    expect(result.molarMass).toBeUndefined()
  })

  it('keeps charge but not coefficient undefined keys out of the result', async () => {
    const result = await executeFormulaMass({ formula: 'H2O' })
    assertLossless(result)
    expect(result.valid).toBe(true)
    expect('charge' in result).toBe(false)
    expect('coefficient' in result).toBe(false)
    expect('hydrate' in result).toBe(false)
  })
})

