/* ------------------------------------------------------------------ */
/* balance_equation (numeric anchors: python oracle balance section)   */
/* ------------------------------------------------------------------ */

interface BalancePayload {
  valid: boolean
  balanced?: boolean
  unique?: boolean
  equation?: string
  reactants?: Array<{ formula: string; coefficient: number }>
  products?: Array<{ formula: string; coefficient: number }>
  elements?: Array<{ symbol: string; left: number; right: number }>
  chargeBalanced?: boolean
  error?: string
}

function coefficientsOf(result: BalancePayload): number[] {
  return [
    ...(result.reactants ?? []).map((term) => term.coefficient),
    ...(result.products ?? []).map((term) => term.coefficient),
  ]
}

/**
 * Oracle: test/anchors-chem.py `balance_equation` section (independent
 * Fraction-based nullspace solver, cross-checked against published textbook
 * coefficients — 1/5/3/4 for propane, 2/16/2/2/5/8 for permanganate/HCl).
 */
const BALANCE_ANCHORS: Array<{ equation: string; coefficients: number[] }> = [
  { equation: 'C3H8 + O2 -> CO2 + H2O', coefficients: [1, 5, 3, 4] },
  { equation: 'Fe + O2 -> Fe2O3', coefficients: [4, 3, 2] },
  { equation: 'KClO3 -> KCl + O2', coefficients: [2, 2, 3] },
  { equation: 'Fe2O3 + CO -> Fe + CO2', coefficients: [1, 3, 2, 3] },
  { equation: 'Al + HCl -> AlCl3 + H2', coefficients: [2, 6, 2, 3] },
  { equation: 'C6H12O6 + O2 -> CO2 + H2O', coefficients: [1, 6, 6, 6] },
  { equation: 'Mg(OH)2 + H3PO4 -> Mg3(PO4)2 + H2O', coefficients: [3, 2, 1, 6] },
  { equation: 'Cu + HNO3 -> Cu(NO3)2 + NO2 + H2O', coefficients: [1, 4, 1, 2, 2] },
  { equation: 'Ca(OH)2 + H3PO4 -> Ca3(PO4)2 + H2O', coefficients: [3, 2, 1, 6] },
  { equation: 'NH3 + O2 -> NO + H2O', coefficients: [4, 5, 4, 6] },
  { equation: 'CH4 + O2 -> CO2 + H2O', coefficients: [1, 2, 1, 2] },
  { equation: 'Fe + HCl -> FeCl2 + H2', coefficients: [1, 2, 1, 1] },
  { equation: 'NaHCO3 -> Na2CO3 + H2O + CO2', coefficients: [2, 1, 1, 1] },
  { equation: 'KMnO4 + HCl -> KCl + MnCl2 + Cl2 + H2O', coefficients: [2, 16, 2, 2, 5, 8] },
  { equation: 'MnO4- + Fe2+ + H+ -> Mn2+ + Fe3+ + H2O', coefficients: [1, 5, 8, 1, 5, 4] },
  { equation: 'Fe2+ + Ce4+ -> Fe3+ + Ce3+', coefficients: [1, 1, 1, 1] },
  { equation: 'Na+ + Cl- -> NaCl', coefficients: [1, 1, 1] },
  { equation: 'CuSO4·5H2O -> CuSO4 + H2O', coefficients: [1, 1, 5] },
  { equation: 'H2 + O2 -> H2O', coefficients: [2, 1, 2] },
]

describe('balance_equation', () => {
  for (const anchor of BALANCE_ANCHORS) {
    it(`balances ${anchor.equation}`, async () => {
      const result = (await executeBalance({ equation: anchor.equation })) as unknown as BalancePayload
      assertLossless(result)
      expect(result.valid).toBe(true)
      expect(result.balanced).toBe(true)
      expect(result.unique).toBe(true)
      expect(coefficientsOf(result)).toEqual(anchor.coefficients)
      for (const element of result.elements!) {
        expect(element.left).toBe(element.right)
      }
    })
  }

  it('accepts "=" and compact separators, and ignores input coefficients', async () => {
    const equals = (await executeBalance({ equation: 'C3H8 + O2 = CO2 + H2O' })) as unknown as BalancePayload
    expect(equals.equation).toBe('C3H8 + 5 O2 -> 3 CO2 + 4 H2O')
    const compact = (await executeBalance({ equation: 'Fe+O2->Fe2O3' })) as unknown as BalancePayload
    expect(coefficientsOf(compact)).toEqual([4, 3, 2])
    // Scaling a column cannot change the solution: the hint is parsed and dropped.
    const hinted = (await executeBalance({ equation: '2H2 + O2 -> 2H2O' })) as unknown as BalancePayload
    expect(coefficientsOf(hinted)).toEqual([2, 1, 2])
  })

  it('omits the coefficient 1 in the rendered equation and reports atom counts', async () => {
    const result = (await executeBalance({ equation: 'C3H8 + O2 -> CO2 + H2O' })) as unknown as BalancePayload
    expect(result.equation).toBe('C3H8 + 5 O2 -> 3 CO2 + 4 H2O')
    const counts = new Map(result.elements!.map((element) => [element.symbol, element]))
    expect(counts.get('C')).toEqual({ symbol: 'C', left: 3, right: 3 })
    expect(counts.get('H')).toEqual({ symbol: 'H', left: 8, right: 8 })
    expect(counts.get('O')).toEqual({ symbol: 'O', left: 10, right: 10 })
    const single = (await executeBalance({ equation: 'Fe + O2 -> Fe2O3' })) as unknown as BalancePayload
    expect(single.equation).toBe('4 Fe + 3 O2 -> 2 Fe2O3')
  })

  it('flags charge conservation when a species carries a charge', async () => {
    const charged = (await executeBalance({ equation: 'MnO4- + Fe2+ + H+ -> Mn2+ + Fe3+ + H2O' })) as unknown as BalancePayload
    expect(charged.chargeBalanced).toBe(true)
    const neutral = (await executeBalance({ equation: 'Fe + O2 -> Fe2O3' })) as unknown as BalancePayload
    expect(neutral.chargeBalanced).toBe(false)
  })

  it('returns the smallest balance and warns when several independent ones exist', async () => {
    // Oracle: three independent balances; smallest total coefficient sum = 15.
    const result = (await executeBalance({ equation: 'Fe + O2 -> Fe2O3 + Fe3O4' })) as unknown as BalancePayload
    assertLossless(result)
    expect(result.valid).toBe(true)
    expect(result.balanced).toBe(true)
    expect(result.unique).toBe(false)
    expect(coefficientsOf(result)).toEqual([7, 5, 2, 1])
    expect(result.equation).toBe('7 Fe + 5 O2 -> 2 Fe2O3 + Fe3O4')
  })

  it('reports "cannot balance" instead of inventing coefficients', async () => {
    for (const equation of ['H2 + O2 -> H2O + N2', 'Na + Cl2 -> NaCl + KCl']) {
      const result = (await executeBalance({ equation })) as unknown as BalancePayload
      assertLossless(result)
      expect(result.valid).toBe(true)
      expect(result.balanced).toBe(false)
      expect(String(result.error)).toContain('coefficient 0')
      expect(result.equation).toBeUndefined()
    }
  })

  it('rejects malformed equations at the parse layer (valid=false)', async () => {
    const noArrow = (await executeBalance({ equation: 'H2 + O2 CO2 + H2O' })) as unknown as BalancePayload
    expect(noArrow.valid).toBe(false)
    expect(String(noArrow.error)).toContain('arrow')
    const twoArrows = (await executeBalance({ equation: 'H2 + O2 -> H2O -> H2O2' })) as unknown as BalancePayload
    expect(twoArrows.valid).toBe(false)
    const unknownElement = (await executeBalance({ equation: 'Xx + O2 -> XxO2' })) as unknown as BalancePayload
    expect(unknownElement.valid).toBe(false)
    expect(String(unknownElement.error)).toContain('Xx')
    const emptySide = (await executeBalance({ equation: 'H2 + O2 -> ' })) as unknown as BalancePayload
    expect(emptySide.valid).toBe(false)
    const oneSpecies = (await executeBalance({ equation: 'H2O -> ' })) as unknown as BalancePayload
    expect(oneSpecies.valid).toBe(false)
  })

  it('rejects a missing equation at the schema layer', async () => {
    await expect(executeBalance({} as { equation: string })).rejects.toThrow()
  })
})

